+++ b/src/gpu/effects/generated/GrCircleBlurFragmentProcessor.cpp
@@ -184,7 +184,7 @@
                                                                   float* solidRadius,
                                                                   float* textureRadius) {
     float circleR = circle.width() / 2.0f;
-    if (circleR < SK_ScalarNearlyZero) {
+    if (!sk_float_isfinite(circleR) || circleR < SK_ScalarNearlyZero) {
         return nullptr;
     }
